  const overBudget = weights.filter((weight) => weight > 32).length;
  const status = enforceBudget && overBudget > 0 ? 400 : 200;
  const row = {
    phase,
    inputCount: texts.length,
    maxRaw: Math.max(0, ...texts.map((text) => text.length)),
    maxWeighted: Math.max(0, ...weights),
    overBudget,
    status,
    upstreamStatus: null as number | null,
    vectorDimensions: [] as number[],
