    },
    {
      "emittedTotalBytes": 33554432,
      "heapDelta": 33718288,
      "externalDelta": 51,
      "active": true,
      "stderrBufferedBytes": 0
    }
  ],
  "fix": [
    {
      "emittedTotalBytes": 16777216,
      "heapDelta": 123496,
      "externalDelta": 51,
      "active": true,
      "stderrBufferedBytes": 0
    },
    {
      "emittedTotalBytes": 33554432,
      "heapDelta": 134080,
