```
</details>

<details>
<summary>Reproduce the owner-level memory measurement</summary>

From the source root, save this as a temporary `.mts` file and run
`node --expose-gc --import ./scripts/tsx.mjs <probe.mts>` on base and candidate.
It substitutes a synthetic child only for `/usr/bin/ssh`; TCP/PID admission and
shutdown remain production code. Its two batches total 32 MiB, and it joins the
owned child before exit.

```ts
import childProcess from 'node:child_process';
import { syncBuiltinESMExports } from 'node:module';
import { once } from 'node:events';
import net from 'node:net';
import { resolve } from 'node:path';

const originalSpawn = childProcess.spawn;
let fixture;
const childCode = `
const net = require('node:net');
const { randomBytes } = require('node:crypto');
const { once } = require('node:events');
const sockets = new Set();
const server = net.createServer(s => { sockets.add(s); s.on('error',()=>{}); s.on('close',()=>sockets.delete(s)); s.end(); });
server.listen(Number(process.argv[1]), '127.0.0.1');
process.on('message', async ({bytes}) => {
 for(let written=0;written<bytes;written+=8192) {
  const chunk=randomBytes(4096).toString('hex');
  if(!process.stderr.write(chunk)) await once(process.stderr,'drain');
 }
 process.send({emitted:bytes});
});
process.on('SIGTERM',()=>{ for(const s of sockets)s.destroy(); server.close(()=>process.exit(0)); });
`;
childProcess.spawn = function(command,args,options) {
 if(command === '/usr/bin/ssh') {
  const forward=args[args.indexOf('-L')+1];
  fixture=originalSpawn(process.execPath,['-e',childCode,forward.split(':')[1]],{...options,stdio:['ignore','ignore','pipe','ipc']});
  return fixture;
 }
 return originalSpawn(command,args,options);
};
syncBuiltinESMExports();
const { startSshPortForward } = await import(resolve('src/infra/ssh-tunnel.ts'));
const reservation = net.createServer();
reservation.listen(0,'127.0.0.1');await once(reservation,'listening');
const port=reservation.address().port;await new Promise(r=>reservation.close(r));
let tunnel;
const memory = async () => {await new Promise(r=>setImmediate(r));global.gc();await new Promise(r=>setImmediate(r));global.gc();const m=process.memoryUsage();return {heapUsed:m.heapUsed,external:m.external};};
try {
 tunnel=await startSshPortForward({target:'synthetic.invalid',localPortPreferred:port,remotePort:18789,timeoutMs:10000});
 const before=await memory(); const checkpoints=[];
 for(let i=0;i<2;i++) {
  const done=once(fixture,'message');fixture.send({bytes:16*1024*1024});await done;
  await new Promise(r=>setTimeout(r,100));
  const m=await memory();checkpoints.push({emittedTotalBytes:(i+1)*16*1024*1024,heapDelta:m.heapUsed-before.heapUsed,externalDelta:m.external-before.external,active:tunnel.isActive(),stderrBufferedBytes:fixture.stderr.readableLength});
 }
 console.log(JSON.stringify({transport:'synthetic child, actual TCP listener and OS PID ownership inspection; not OpenSSH',before,checkpoints}));
} finally {
 await tunnel?.stop();
 if(fixture && fixture.exitCode===null && fixture.signalCode===null) {fixture.kill('SIGKILL');await once(fixture,'close');}
 childProcess.spawn=originalSpawn;syncBuiltinESMExports();
 console.log(JSON.stringify({cleanup:true,childExitCode:fixture?.exitCode,childSignal:fixture?.signalCode}));
}

```
</details>

### Regression and checks

Extended the existing startup-diagnostic regression with a noisy UTF-8 case,
keeping the exact original small-message assertion. The new case failed on base
and passes on the fix, with a bounded message, explicit clipping notice and no
broken UTF-8. All 26 tunnel tests and the existing process-output retention test
passed. Production/test typechecks, focused lint/formatting, the line-cap check
and whitespace checks passed.

```sh
node scripts/test-projects.mts src/infra/ssh-tunnel.test.ts src/process/exec-output.retention.test.ts
node scripts/run-tsgo.mjs -p tsconfig.core.json --incremental
node scripts/run-tsgo.mjs -p test/tsconfig/tsconfig.core.test.infra.json --incremental
node scripts/run-oxlint.mjs --format json --tsconfig tsconfig.core.json src/infra/ssh-tunnel.ts src/infra/ssh-tunnel.test.ts
pnpm exec oxfmt --check src/infra/ssh-tunnel.ts src/infra/ssh-tunnel.test.ts
```

### Independent review focus

The remaining live integration check is a persistent Gateway connection through
real OpenSSH with verbose diagnostics: keep the route usable while output
accumulates, then disconnect and confirm the owned child exits. The bounded
owner experiment and regression results above are available for comparison;
that full SSH/Gateway session has not been run here.

issues.body:
### Affected component

tooling/ci

### Severity

S3 - minor issue

### Current behavior

A test that sends an HTTP request to a local mock server occasionally fails with:

```text
error sending request for url (http://127.0.0.1:33775/v1/messages)
Caused by:
    0: client error (SendRequest)
    1: dispatch task is gone
    2: runtime dropped the dispatch task
```

It has been the only failure of a Parallel Runtime Test run at least twice, in two crates:
- `agent::agent::safety_net::usage_event_coherent_tuple_vision_route` (`zeroclaw-runtime`), in the merge-queue run for #11266 on 2026-11-04 (run 41932479909);
- `telegram::tests::timeout_wins_claim_and_late_callback_is_a_stale_no_edit` (`zeroclaw-channels`), reported in a comment on #10262 on 2026-09-03.

The cause is the process-wide client cache in `zeroclaw-config`, combined with wiremock's process-wide server pool:

1. `RUNTIME_PROXY_CLIENT_CACHE` (`crates/zeroclaw-config/src/schema.rs:116`) returns one `reqwest::Client` per service key to every caller in the process. Every caller of `build_runtime_proxy_client*` and `build_channel_proxy_client*` goes through it: 68 call sites in 48 files. Two examples are the Anthropic provider's non-streaming client (`crates/zeroclaw-providers/src/anthropic.rs:2402-2408`) and Telegram's client (`build_channel_proxy_client`, `schema.rs:12083-12088`). In a test binary, every `#[tokio::test]` therefore shares these clients and their connection pools.
2. hyper runs each pooled connection as a task spawned on whichever runtime opened it (hyper-util `rt/tokio.rs:112`). When the pool hands out an idle connection, it checks only that the connection is ready (hyper-util `client/legacy/client.rs:854`), not which runtime drives it.
3. wiremock 0.6 hands out mock servers from a process-wide pool (`mock_server/pool.rs:24`). Each server runs on its own thread, so a later test can get the same port while the server keeps its keep-alive connections.

So test B can send over an idle connection that test A opened. If test A finishes while B's request is in flight, A's runtime drops the connection task with B's request inside it, and hyper reports `dispatch task is gone: runtime dropped the dispatch task` (hyper `client/dispatch.rs:236-263`). A connection whose runtime has already ended isn't reused: the pool drops it. The failure needs A to still be running when B takes the connection, and to end before the response arrives.

In the 2026-11-04 failure, test A was most likely `usage_event_coherent_tuple_in_turn_model_switch`. It has the same shape as the failing test: two cells, a pooled `MockServer` each, and an Anthropic provider at the default timeout. Its name also sorts next to the failing test's, so the two start together. Any test that drives an Anthropic provider at the default timeout against a pooled wiremock server could play that part.

### Expected behavior

A test's HTTP request isn't affected by another test's runtime ending.

### Steps to reproduce

```bash
# Deterministic. The probe (a #[cfg(test)] module appended to
# crates/zeroclaw-providers/src/anthropic.rs, attached below) has two runtimes
# share the cached Anthropic client. Runtime A sends once and stays alive.
# Runtime B sends to a server that delays its answer by 500 ms, and A ends
# 150 ms into B's request.
cargo test -p zeroclaw-providers --lib -- cross_runtime_pool_probe --test-threads=1 --nocapture
# Result on master 683d10139b: B fails with the error chain above in 10 of 10 runs.
# Two controls pass in 10 of 10 runs:
#   - B with a client of its own (a different timeout, so a different cache key);
#   - A's runtime ending before B sends.
```

On its own the race is rare. On a 32-core Linux host it didn't recur in:
- 18 runs of `cargo test -p zeroclaw-runtime --lib -- --test-threads=16` on master, five of them pinned to 8 CPUs;
- 300 runs of the two `usage_event_coherent_tuple_*` tests together at 16 threads;
- 50 runs of the failing test alone.

### Impact

Test and CI noise. One occurrence ejects a PR from the merge queue and looks like a regression in that PR.

Production uses the same cache. It mostly runs one runtime, but three places start short-lived runtimes on their own threads:
- the SOP capability bridge (`crates/zeroclaw-runtime/src/sop/capability/bridge.rs:32`);
- the Gemini managed-OAuth probe (`crates/zeroclaw-providers/src/gemini.rs:609`);
- the plugin probe (`crates/zeroclaw-plugins/src/wasm_tool.rs:140`).

I haven't checked whether any of them sends through a cached client.

### Logs / stack traces

```text
thread 'agent::agent::safety_net::usage_event_coherent_tuple_vision_route' (4766) panicked at crates/zeroclaw-runtime/src/agent/safety_net.rs:3174:14:
turn should succeed: StreamedTurnError { error: error sending request for url (http://127.0.0.1:33775/v1/messages)

Caused by:
    0: client error (SendRequest)
    1: dispatch task is gone
    2: runtime dropped the dispatch task, committed_response: "[stream interrupted]", ... }
```

### ZeroClaw version

master 683d10139b

### Rust version

1.98.0

### Operating system

Linux x86_64 (Ubuntu 24.04)

### Regression?

Unknown

### Pre-flight checks

- [X] I reproduced this on the latest master branch or latest release.
- [X] I redacted secrets, tokens, and personal data from all submitted content.

### Fix idea

Stop test runtimes from sharing pooled connections. The smallest change: in test builds, have the cached builders set `pool_max_idle_per_host(0)`. Put that behind a `zeroclaw-config` feature that the dev-dependencies of `zeroclaw-runtime`, `zeroclaw-channels` and `zeroclaw-providers` enable. The cache still returns one client per key, so its own reuse tests are unaffected, and each request opens its connection on the runtime that sends it. I tried this on the probe: with idle pooling off, B's request succeeds in 10 of 10 runs, and the same build without it fails in 10 of 10. The cost is more short-lived loopback connections during test runs.

If one of the production runtimes above does send through a cached client, the fix belongs in the cache itself, not just in test builds. One option is to keep the cache per thread.

<details><summary>Probe</summary>

```diff
diff --git a/crates/zeroclaw-providers/src/anthropic.rs b/crates/zeroclaw-providers/src/anthropic.rs
index 484ec049ea..1a2737da97 100644
--- a/crates/zeroclaw-providers/src/anthropic.rs
+++ b/crates/zeroclaw-providers/src/anthropic.rs
@@ -11257,3 +11257,143 @@ data: {\"type\":\"message_stop\"}\n\n";
         );
     }
 }
+
+/// Reproduction probe: a cached client's pooled connection is
+/// driven by the runtime that opened it, so a request from another runtime
+/// that rides it fails if that runtime ends mid-request.
+#[cfg(test)]
+mod cross_runtime_pool_probe {
+    use super::*;
+    use std::sync::Arc;
+    use std::sync::atomic::{AtomicUsize, Ordering};
+    use std::time::Duration;
+
+    /// Serve `/v1/messages` on its own thread and runtime, as wiremock's
+    /// pooled servers do. Every request after the first waits `delay`.
+    fn serve(delay: Duration) -> String {
+        use axum::{Json, Router, routing::post};
+        let (tx, rx) = std::sync::mpsc::channel();
+        let hits = Arc::new(AtomicUsize::new(0));
+        std::thread::spawn(move || {
+            let rt = tokio::runtime::Builder::new_current_thread()
+                .enable_all()
+                .build()
+                .unwrap();
+            rt.block_on(async move {
+                let app = Router::new().route(
+                    "/v1/messages",
+                    post(move |Json(_b): Json<serde_json::Value>| {
+                        let hits = hits.clone();
+                        async move {
+                            if hits.fetch_add(1, Ordering::SeqCst) > 0 {
+                                tokio::time::sleep(delay).await;
+                            }
+                            Json(serde_json::json!({
+                                "content": [{"type": "text", "text": "ok"}],
+                                "usage": {"input_tokens": 1, "output_tokens": 1},
+                                "stop_reason": "end_turn",
+                                "model": "probe-model"
+                            }))
+                        }
+                    }),
+                );
+                let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
+                tx.send(format!("http://{}", listener.local_addr().unwrap()))
+                    .unwrap();
+                axum::serve(listener, app).await.unwrap();
+            });
+        });
+        rx.recv().unwrap()
+    }
+
+    fn provider(url: &str, timeout_secs: u64) -> AnthropicModelProvider {
+        AnthropicModelProvider::builder("probe")
+            .credential(Some("test-key"))
+            .base_url(url)
+            .timeout_secs(timeout_secs)
+            .build()
+    }
+
+    fn rt() -> tokio::runtime::Runtime {
+        tokio::runtime::Builder::new_current_thread()
+            .enable_all()
+            .build()
+            .unwrap()
+    }
+
+    /// Runtime A sends once, so its connection sits idle in the cached
+    /// client's pool, then stays alive until told to stop.
+    fn runtime_a(
+        url: String,
+        timeout_secs: u64,
+    ) -> (tokio::sync::oneshot::Sender<()>, std::thread::JoinHandle<()>) {
+        let (ready_tx, ready_rx) = std::sync::mpsc::channel();
+        let (stop_tx, stop_rx) = tokio::sync::oneshot::channel::<()>();
+        let handle = std::thread::spawn(move || {
+            let rt_a = rt();
+            rt_a.block_on(async move {
+                provider(&url, timeout_secs)
+                    .chat_with_system(None, "a", "probe-model", None)
+                    .await
+                    .expect("runtime A's request");
+                ready_tx.send(()).unwrap();
+                let _ = stop_rx.await;
+            });
+            drop(rt_a);
+        });
+        ready_rx.recv().unwrap();
+        (stop_tx, handle)
+    }
+
+    /// Runtime B sends while A is alive; A ends `end_a_after` into B's request.
+    fn request_from_b_while_a_ends(
+        url: &str,
+        timeout_secs_b: u64,
+        stop_a: tokio::sync::oneshot::Sender<()>,
+        end_a_after: Duration,
+    ) -> anyhow::Result<String> {
+        let rt_b = rt();
+        rt_b.block_on(async move {
+            let p = provider(url, timeout_secs_b);
+            let req = p.chat_with_system(None, "b", "probe-model", None);
+            tokio::pin!(req);
+            tokio::select! {
+                r = &mut req => return r,
+                () = tokio::time::sleep(end_a_after) => {}
+            }
+            let _ = stop_a.send(());
+            req.await
+        })
+    }
+
+    #[test]
+    fn probe_shared_cached_client_fails_when_the_connections_runtime_ends_mid_request() {
+        let url = serve(Duration::from_millis(500));
+        let (stop_a, a) = runtime_a(url.clone(), 4242);
+        let r = request_from_b_while_a_ends(&url, 4242, stop_a, Duration::from_millis(150));
+        a.join().unwrap();
+        let chain = format!("{:#}", r.expect_err("B's request rode A's pooled connection"));
+        println!("PROBE-ERROR-CHAIN: {chain}");
+        assert!(chain.contains("dispatch task is gone"), "{chain}");
+        assert!(chain.contains("runtime dropped the dispatch task"), "{chain}");
+    }
+
+    #[test]
+    fn probe_control_a_client_of_its_own_is_unaffected() {
+        let url = serve(Duration::from_millis(500));
+        let (stop_a, a) = runtime_a(url.clone(), 4243);
+        let r = request_from_b_while_a_ends(&url, 4244, stop_a, Duration::from_millis(150));
+        a.join().unwrap();
+        r.expect("B has its own client, so its own connection");
+    }
+
+    #[test]
+    fn probe_control_a_connection_from_an_ended_runtime_is_not_reused() {
+        let url = serve(Duration::from_millis(500));
+        let (stop_a, a) = runtime_a(url.clone(), 4245);
+        let _ = stop_a.send(());
+        a.join().unwrap();
+        rt().block_on(provider(&url, 4245).chat_with_system(None, "b", "probe-model", None))
+            .expect("the pool drops a connection whose runtime has ended");
+    }
+}
```

</details>

prs.body:
---
name: odt
description: "Use this skill whenever the user wants to create, fill, read, or convert OpenDocument Format files (.odt, .ods). Triggers include: any mention of 'ODT', 'ODS', 'ODF', 'OpenDocument', 'LibreOffice document', or requests to produce documents in open-source or ISO standard formats. Also use when converting HTML, Markdown, or TipTap/ProseMirror JSON to ODT, filling ODT templates with data, reading or extracting content from ODT files, generating ODS spreadsheets, reading ODS files, converting XLSX to ODS, converting DOCX to ODT, or creating formal documents like resolutions, reports, letters, contracts, invoices, or memos as .odt files. Use this skill instead of the docx skill when the user explicitly requests .odt output or mentions LibreOffice/OpenOffice as their target application. Do NOT use for .docx files (use the docx skill), PDFs, presentations, or general coding tasks unrelated to document generation."
license: Apache-2.0
---

# odf-kit — OpenDocument Format for JavaScript and TypeScript

## Overview

An `.odt` file is an OpenDocument Format text document — an ISO standard (ISO/IEC 26300) ZIP archive containing XML files. It is the native format for LibreOffice, Apache OpenOffice, Collabora, OnlyOffice, and is supported by Google Docs and Microsoft Office.

odf-kit is the only actively maintained JavaScript/TypeScript library for ODF generation. It produces spec-validated output (validated against the OASIS ODF Validator on every CI run). Works in Node.js 22+ and browsers. No LibreOffice dependency.

## Quick Reference

| Task | Import | Function |
|------|--------|----------|
| Create new ODT document | `"odf-kit"` | `new OdtDocument()` |
| Fill existing ODT template | `"odf-kit"` | `fillTemplate(bytes, data)` |
| HTML → ODT | `"odf-kit"` | `htmlToOdt(html, options?)` |
| Markdown → ODT | `"odf-kit"` | `markdownToOdt(markdown, options?)` |
| TipTap/ProseMirror JSON → ODT | `"odf-kit"` | `tiptapToOdt(json, options?)` |
| Build ODS spreadsheet | `"odf-kit"` | `new OdsDocument()` |
| Read ODT / convert to HTML | `"odf-kit/reader"` | `readOdt(bytes)` / `odtToHtml(bytes)` |
| Read ODS | `"odf-kit/ods-reader"` | `readOds(bytes)` / `odsToHtml(bytes)` |
| XLSX → ODS | `"odf-kit/xlsx"` | `xlsxToOds(bytes)` |
| DOCX → ODT | `"odf-kit/docx"` | `docxToOdt(bytes, options?)` |
| ODT → Typst / PDF | `"odf-kit/typst"` | `odtToTypst(bytes)` |

### Installation

```bash
npm install odf-kit
```

Requires Node.js 22 or later. ESM only.

---

## Creating New ODT Documents

Generate .odt files with JavaScript using odf-kit's builder API.

### Setup

```javascript
import { OdtDocument } from "odf-kit";
import { writeFileSync } from "fs";

const doc = new OdtDocument();
doc.addHeading("Document Title", 1);
doc.addParagraph("Body text goes here.");

const bytes = await doc.save();
writeFileSync("output.odt", bytes);
```

### Metadata

```javascript
doc.setMetadata({
  title: "Quarterly Report",
  creator: "Jane Doe",
  description: "Q4 2026 financial summary",
});
```

### Page Layout

```javascript
doc.setPageLayout({
  orientation: "landscape",       // or "portrait" (default)
  width: "21cm",                  // default A4
  height: "29.7cm",
  marginTop: "2cm",
  marginBottom: "2cm",
  marginLeft: "2cm",
  marginRight: "2cm",
});
```

**For US Letter:** Use `width: "8.5in"` and `height: "11in"`.

### Headers and Footers

```javascript
// Simple string (### = page number)
doc.setHeader("Confidential — Page ###");
doc.setFooter("© 2026 Acme Corp — Page ###");

// Builder for formatted headers
doc.setHeader((h) => {
  h.addText("Confidential", { bold: true, color: "gray" });
  h.addText(" — Page ");
  h.addPageNumber();
});
```

### Headings

```javascript
// Basic heading (levels 1–6)
doc.addHeading("Chapter Title", 1);
doc.addHeading("Section Title", 2);

// With paragraph options
doc.addHeading("Centered Title", 1, { align: "center" });
doc.addHeading("Title with Space", 1, { spaceBefore: "0.5cm", spaceAfter: "0.5cm" });
```

### Paragraphs

```javascript
// Plain text
doc.addParagraph("Simple paragraph.");

// With paragraph options
doc.addParagraph("Right-aligned text.", { align: "right" });

// Builder for mixed formatting
doc.addParagraph((p) => {
  p.addText("Normal and ");
  p.addText("bold", { bold: true });
  p.addText(" text.");
});

// Builder with paragraph options
doc.addParagraph((p) => {
  p.addText("Indented paragraph content.");
}, { indentLeft: "1cm", indentFirst: "0.5cm" });
```

**Paragraph options:**

| Option | Type | Example | Description |
|--------|------|---------|-------------|
| `align` | string | `"left"`, `"center"`, `"right"`, `"justify"` | Text alignment |
| `spaceBefore` | string | `"0.5cm"` | Space above paragraph |
| `spaceAfter` | string | `"0.5cm"` | Space below paragraph |
| `lineHeight` | number or string | `1.5` or `"150%"` | Line spacing (number = multiplier) |
| `indentLeft` | string | `"1cm"` | Left indent |
| `indentRight` | string | `"1cm"` | Right indent |
| `indentFirst` | string | `"0.5cm"` | First-line indent (positive) or hanging indent (negative) |
| `tabStops` | array | `[{ position: "6cm", type: "right" }]` | Tab stop positions |

### Text Formatting

```javascript
doc.addParagraph((p) => {
  p.addText("Bold", { bold: true });
  p.addText("Italic", { italic: true });
  p.addText("Underline", { underline: true });
  p.addText("Strikethrough", { strikethrough: true });
  p.addText("Super", { superscript: true });
  p.addText("Sub", { subscript: true });
  p.addText("Arial 14pt red", { fontFamily: "Arial", fontSize: 14, color: "#CC0000" });
  p.addText("Highlighted", { highlightColor: "#FFFF00" });
  p.addText("UPPERCASE", { textTransform: "uppercase" });
  p.addText("Small Caps", { smallCaps: true });
  p.addText("Weight 300", { fontWeight: 300 });   // numeric 100–900
  p.addText("Weight bold", { fontWeight: "bold" });
});
```

**All text formatting options:**

| Option | Type | Example |
|--------|------|---------|
| `bold` | boolean | `true` |
| `italic` | boolean | `true` |
| `underline` | boolean | `true` |
| `strikethrough` | boolean | `true` |
| `superscript` | boolean | `true` |
| `subscript` | boolean | `true` |
| `fontSize` | number or string | `14` or `"14pt"` |
| `fontFamily` | string | `"Arial"` |
| `fontWeight` | string or number | `"bold"`, `300`, `700` |
| `fontStyle` | string | `"normal"`, `"italic"` |
| `color` | string | `"#FF0000"` or `"red"` |
| `highlightColor` | string | `"#FFFF00"` or `"yellow"` |
| `textTransform` | string | `"uppercase"`, `"lowercase"`, `"capitalize"` |
| `smallCaps` | boolean | `true` |

### Tables

```javascript
// Simple — array of arrays
doc.addTable([
  ["Name", "Role", "Department"],
  ["Alice", "Engineer", "R&D"],
  ["Bob", "Designer", "UX"],
]);

// With options
doc.addTable([
  ["Item", "Price"],
  ["Widget", "$9.99"],
], { columnWidths: ["8cm", "4cm"], border: "0.5pt solid #000000" });

// Full control — builder callback
doc.addTable((t) => {
  t.addRow((r) => {
    r.addCell("Header", {
      bold: true,
      backgroundColor: "#DDDDDD",
      verticalAlign: "middle",
      padding: "0.15cm",
    });
    r.addCell("Value", {
      bold: true,
      backgroundColor: "#DDDDDD",
      colSpan: 2,
    });
  }, { backgroundColor: "#DDDDDD" });

  t.addRow((r) => {
    r.addCell("Status");
    r.addCell("Complete", { color: "green" });
    r.addCell("Verified", { border: "0.5pt solid #000000" });
  });

  // Row spanning
  t.addRow((r) => {
    r.addCell("Tall", { rowSpan: 2, verticalAlign: "top" });
    r.addCell("Normal");
  });
  t.addRow((r) => {
    r.addCell("Adjacent to rowspan");
  });
}, { columnWidths: ["4cm", "4cm", "4cm"] });
```

**Cell options** (extends all text formatting options, plus):

| Option | Type | Example |
|--------|------|---------|
| `backgroundColor` | string | `"#EEEEEE"` |
| `border` | string | `"0.5pt solid #000000"` |
| `borderTop` / `borderBottom` / `borderLeft` / `borderRight` | string | Per-side borders |
| `colSpan` | number | `2` |
| `rowSpan` | number | `3` |
| `verticalAlign` | string | `"top"`, `"middle"`, `"bottom"` |
| `padding` | string | `"0.15cm"` |

### Lists

```javascript
// Simple bullet list
doc.addList(["Apples", "Bananas", "Cherries"]);

// Numbered list
doc.addList(["First", "Second", "Third"], { type: "numbered" });

// Alpha / roman / custom formats
doc.addList(["Item a", "Item b"], { type: "numbered", numFormat: "a" });
doc.addList(["Item A", "Item B"], { type: "numbered", numFormat: "A" });
doc.addList(["Item i", "Item ii"], { type: "numbered", numFormat: "i" });
doc.addList(["Step 5", "Step 6"], { type: "numbered", startValue: 5 });
doc.addList(["Item", "Item"], { type: "numbered", numPrefix: "(", numSuffix: ")" });

// Nested with formatting — builder callback
doc.addList((l) => {
  l.addItem((p) => {
    p.addText("Important: ", { bold: true });
    p.addText("read the documentation");
  });
  l.addItem("Main topic");
  l.addNested((sub) => {
    sub.addItem("Subtopic A");
    sub.addItem("Subtopic B");
  });
});
```

**List options:**

| Option | Type | Example | Description |
|--------|------|---------|-------------|
| `type` | string | `"numbered"` | `"bullet"` (default) or `"numbered"` |
| `numFormat` | string | `"a"`, `"A"`, `"i"`, `"I"` | Number format; default `"1"` |
| `numPrefix` | string | `"("` | Text before number |
| `numSuffix` | string | `")"` | Text after number; default `"."` |
| `startValue` | number | `5` | Starting number |

### Images

```javascript
import { readFile } from "fs/promises";
const logo = await readFile("logo.png");

// Standalone
doc.addImage(logo, { width: "10cm", height: "6cm", mimeType: "image/png" });

// Inline in text
doc.addParagraph((p) => {
  p.addText("Logo: ");
  p.addImage(logo, { width: "2cm", height: "1cm", mimeType: "image/png" });
});
```

**Image options:**

| Option | Type | Required | Description |
|--------|------|----------|-------------|
| `width` | string | Yes | `"10cm"`, `"4in"` |
| `height` | string | Yes | `"6cm"`, `"3in"` |
| `mimeType` | string | Yes | `"image/png"`, `"image/jpeg"` |
| `anchor` | string | No | `"as-character"` or `"paragraph"` |

### Links and Bookmarks

```javascript
// External URL
doc.addParagraph((p) => {
  p.addText("Visit ");
  p.addLink("our website", "https://example.com", { bold: true });
});

// Internal bookmark target
doc.addParagraph((p) => {
